.rasa-ui{--rui-bg:#f7f9fe;--rui-card:#fff;--rui-text:#182642;--rui-muted:#53647c;--rui-line:#c6d2e5;--rui-accent:#365de1;--rui-soft:#edf3ff;color:var(--rui-text);font-family:inherit;line-height:1.8;text-align:start}.rasa-ui[data-mode=dark],[data-theme=dark] .rasa-ui:not([data-mode=light]){--rui-bg:#0b172b;--rui-card:#12263e;--rui-text:#edf6ff;--rui-muted:#bacce1;--rui-line:#496783;--rui-accent:#9edaff;--rui-soft:#203b56}.rasa-ui[data-style=editorial]{--rui-accent:#5d4a99;--rui-soft:#f1ecfa;--rui-line:#cfc4e2}.rasa-ui[data-style=vivid]{--rui-accent:#365de1;--rui-soft:#dceeff;--rui-line:#9abcf3}.rasa-ui[data-mode=dark][data-style=editorial]{--rui-accent:#d3bdff;--rui-soft:#322a4f;--rui-line:#786b91}.rasa-ui[data-mode=dark][data-style=vivid]{--rui-accent:#9addff;--rui-soft:#163f64;--rui-line:#5286b3}.rasa-ui *{box-sizing:border-box}.rasa-ui button,.rasa-ui input,.rasa-ui textarea{font-family:inherit}.rasa-ui button{cursor:pointer}.rasa-ui button:focus-visible,.rasa-ui a:focus-visible,.rasa-ui input:focus-visible,.rasa-ui summary:focus-visible,.rasa-ui textarea:focus-visible{outline:3px solid var(--rui-accent);outline-offset:3px}.rasa-ui button:disabled{cursor:default}.rui-action-wrap{display:grid;place-items:center;gap:15px;padding:25px}.rasa-ui .rui-action{background:#365de1;color:#fff;border:1px solid #7c9bf2;min-height:45px;padding:10px 25px;border-radius:30px;box-shadow:inset 0 1px 0 #fff5,0 8px 25px #365de12a;transition:transform .18s,box-shadow .18s}.rasa-ui .rui-action:hover{background:#294ac2;box-shadow:0 10px 30px #365de145}.rasa-ui .rui-action:active{transform:scale(.97)}.rasa-ui .rui-action:disabled{background:#e1e7f1;color:#43546d;border-color:#8b9bb5;opacity:1}.rui-action-wrap>span{font-size:11px;min-height:20px}.rui-tabs{width:100%;max-width:450px}.rui-tabs>[role=tablist]{display:flex;background:var(--rui-soft);padding:5px;border-radius:18px;border:1px solid var(--rui-line)}.rui-tabs [role=tab]{flex:1;padding:10px;border-radius:13px;background:transparent;border:0;color:var(--rui-muted);font-size:12px;transition:background .2s,box-shadow .2s}.rui-tabs [role=tab][aria-selected=true]{background:var(--rui-card);color:var(--rui-text);box-shadow:0 3px 10px #0001}.rui-tabs [role=tabpanel]{padding:23px 12px;font-size:13px;min-height:100px;line-height:2}.rui-disclosure{width:100%;padding:18px 20px;border:1px solid var(--rui-line);background:var(--rui-card);border-radius:18px;font-size:13px}.rui-disclosure summary{display:flex;justify-content:space-between;gap:15px;cursor:pointer;list-style:none;font-weight:600}.rui-disclosure summary::-webkit-details-marker{display:none}.rui-disclosure summary>span{color:var(--rui-accent);transition:transform .2s}.rui-disclosure[open] summary>span{transform:rotate(45deg)}.rui-disclosure p{color:var(--rui-muted);font-size:12px;line-height:2;margin:18px 0 0}.rui-slider{width:100%;padding:25px;border:1px solid var(--rui-line);border-radius:20px;background:var(--rui-card)}.rui-slider label{display:flex;justify-content:space-between;align-items:center;font-size:13px}.rui-slider output{border-radius:10px;background:var(--rui-soft);padding:4px 14px;color:var(--rui-text)}.rui-slider input{width:100%;accent-color:var(--rui-accent);margin:25px 0 10px}.rui-slider>div{display:flex;justify-content:space-between;color:var(--rui-muted);font-size:10px}.rui-metric{display:flex;align-items:center;justify-content:space-between;gap:20px;padding:25px;border:1px solid var(--rui-line);background:var(--rui-card);border-radius:20px;width:100%}.rui-metric span{font-size:11px;color:var(--rui-muted)}.rui-metric strong{display:block;font-size:34px;line-height:1.6}.rui-metric small{font-size:10px;font-weight:400;margin-inline-start:8px}.rui-metric svg{width:45%;max-width:160px;overflow:visible;color:var(--rui-accent)}.rui-comparison{width:100%;padding:20px}.rui-comparison [role=group]{display:grid;gap:14px}.rui-comparison button{display:grid;grid-template-columns:55px 1fr 30px;align-items:center;gap:12px;width:100%;border:0;background:transparent;padding:5px;color:var(--rui-text);font-size:11px;text-align:start}.rui-comparison i{height:15px;background:var(--rui-soft);border-radius:5px;overflow:hidden}.rui-comparison b{display:block;height:100%;background:var(--rui-accent);border-radius:5px;transition:width .3s}.rui-comparison button[aria-pressed=true] i{outline:2px solid var(--rui-accent);outline-offset:3px}.rui-comparison p{color:var(--rui-muted);font-size:11px;margin-top:20px;min-height:20px}.rui-share{display:flex;align-items:center;gap:25px;padding:15px;width:100%;justify-content:center}.rui-share-ring{width:150px;height:150px;border-radius:50%;padding:17px;flex-shrink:0;transform:rotate(-15deg)}.rui-share-ring>span{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:5px;width:100%;height:100%;border-radius:50%;background:var(--rui-card);transform:rotate(15deg)}.rui-share strong{font-size:26px}.rui-share small{font-size:10px;color:var(--rui-muted)}.rui-share>div:last-child{display:grid;gap:10px}.rui-share button{display:flex;gap:8px;align-items:center;background:transparent;border:1px solid transparent;border-radius:10px;padding:8px;color:var(--rui-text);font-size:11px}.rui-share button[aria-pressed=true]{background:var(--rui-soft);border-color:var(--rui-line)}.rui-share button i{width:8px;height:8px;border-radius:3px}.rui-source{width:100%;padding:25px;background:var(--rui-card);border:1px solid var(--rui-line);border-radius:18px}.rui-source>span,.rui-product>span{font-size:10px;color:var(--rui-accent)}.rui-source h3,.rui-product h3{font-size:20px;margin:12px 0}.rui-source p,.rui-product p{font-size:12px;line-height:2;color:var(--rui-muted)}.rui-source a,.rui-product a{display:flex;justify-content:space-between;gap:15px;align-items:center;color:var(--rui-accent);font-size:12px;padding-top:18px;margin-top:20px;border-top:1px solid var(--rui-line);text-decoration:none}.rui-flow{width:100%}.rui-flow ol{display:grid;gap:14px;padding:0;list-style:none;margin:0}.rui-flow li{display:flex;gap:12px;align-items:center;font-size:12px;color:var(--rui-muted)}.rui-flow li>span{display:grid;place-items:center;width:28px;height:28px;border:1px solid var(--rui-line);border-radius:50%;font-size:11px}.rui-flow li[data-state=current]{color:var(--rui-text)}.rui-flow li[data-state=current]>span{background:var(--rui-accent);color:var(--rui-bg)}.rui-flow li[data-state=done]>span{background:var(--rui-soft);color:var(--rui-accent)}.rui-flow>button{margin-top:20px;border:1px solid var(--rui-line);background:var(--rui-card);color:var(--rui-text);border-radius:12px;padding:9px 15px;font-size:11px}.rui-flow p{font-size:9px;color:var(--rui-muted)}.rui-composer{width:100%;border:1px solid var(--rui-line);border-radius:20px;padding:20px;background:var(--rui-card)}.rui-composer label{font-size:15px;font-weight:600}.rui-composer textarea{display:block;width:100%;min-height:90px;resize:vertical;border:0;background:transparent;color:var(--rui-text);font-size:12px;line-height:2;padding:18px 0}.rui-composer textarea::placeholder{color:var(--rui-muted)}.rui-composer>div{display:flex;justify-content:space-between;align-items:center;border-top:1px solid var(--rui-line);padding-top:12px;gap:10px}.rui-composer>div>span{font-size:9px;color:var(--rui-muted)}.rui-composer button{padding:8px 13px;border-radius:20px;border:0;background:#365de1;color:#fff;font-size:11px}.rui-composer button:disabled{background:var(--rui-soft);color:var(--rui-muted)}.rui-composer p{font-size:10px;color:var(--rui-muted);min-height:18px;margin:10px 0 0}.rui-quote{width:100%;padding:25px;border:1px solid var(--rui-line);border-radius:20px;background:var(--rui-card)}.rui-quote>span{font-size:11px;color:var(--rui-muted)}.rui-quote strong{display:block;font-size:29px;margin:15px 0}.rui-quote strong small{font-size:11px;font-weight:400}.rui-quote label{display:flex;gap:10px;font-size:12px;align-items:center}.rui-quote input{accent-color:var(--rui-accent);width:17px;height:17px}.rui-quote p{font-size:10px;color:var(--rui-muted);margin-top:20px}.rui-product{width:100%;background:var(--rui-card);border:1px solid var(--rui-line);border-radius:20px;padding:20px;overflow:hidden}.rui-product-art{height:120px;display:flex;gap:10px;align-items:flex-end;background:var(--rui-soft);padding:20px;border-radius:14px;margin-bottom:20px}.rui-product-art i{flex:1;background:var(--rui-accent);border-radius:5px 5px 0 0;opacity:.8;transition:transform .3s}.rui-product:hover .rui-product-art i{transform:scaleY(1.05);transform-origin:bottom}.rui-product a{margin-top:12px;padding-top:12px}
@media(max-width:420px){.rui-share{gap:12px;padding:10px 0}.rui-share-ring{width:125px;height:125px;padding:14px}.rui-share button{font-size:10px;padding:7px}.rui-metric{padding:20px;gap:10px}.rui-metric strong{font-size:29px}}
@media(prefers-reduced-motion:reduce){.rasa-ui *{transition:none!important;animation:none!important}}
